function validate(input) {
  const [{ Employees = [], Salaries = [] }] = input;
  const named = new Set(), paid = new Set();
  for (const [id, name] of Employees) {
    if (id === null) return 'Every Employees row needs an employee_id.';
    if (named.has(id)) return `employee_id ${id} appears twice in Employees.`;
    if (name === null) return `Employee ${id} needs a name.`;
    named.add(id);
  }
  for (const [id, salary] of Salaries) {
    if (id === null) return 'Every Salaries row needs an employee_id.';
    if (paid.has(id)) return `employee_id ${id} appears twice in Salaries.`;
    if (salary === null) return `Employee ${id} needs a salary value.`;
    paid.add(id);
  }
  return null;
}

