function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  const names = ['Crew', 'Haven', 'Kristian', 'Ana', 'Bob', 'Lee', 'Mia', 'Omar'];
  const pool = small ? 10 : 2600, cap = small ? pick(9) : 2000;
  const Employees = [], Salaries = [];
  for (let id = 1; id <= pool; id++) {
    // Each id is in both tables, only one of them, or neither.
    const r = rand();
    const inEmployees = r < 0.65, inSalaries = r < 0.5 || r >= 0.8;
    if (inEmployees && Employees.length < cap) Employees.push([id, names[pick(names.length)]]);
    if (inSalaries && Salaries.length < cap) Salaries.push([id, 1000 * (20 + pick(80)) + pick(1000)]);
  }
  const shuffle = rows => { for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; } return rows; };
  return [{ Employees: shuffle(Employees), Salaries: shuffle(Salaries) }];
}
